func TestLostResponse(t *testing.T) {
	// No keep-alive: net/http itself retries a GET whose reused connection drops, which would hide the SDK's retry.
	h := setup(t, WithMaxRetries(1), WithHTTPClient(&http.Client{Transport: &http.Transport{DisableKeepAlives: true}}))
	h.mock.reply(mockReply{destroy: true}, okReply(map[string]any{"ok": 1}, nil))
	res, err := h.get(nil)
	if err != nil || res.Data["ok"] != 1.0 || len(h.mock.reqs()) != 2 || !h.mock.reqs()[1].Query.Has("max_age") {
		t.Fatalf("lost response: %v %v", res, err)
	}
	h.mock.reply(mockReply{destroy: true}, mockReply{destroy: true})
	var ce *ConnectionError
	if _, err := h.get(nil); !errors.As(err, &ce) {
		t.Errorf("err: %v", err)
	}
}

