func TestIterateGuards(t *testing.T) {
	h := setup(t)
	more := map[string]any{"has_more": true, "next_cursor": "c1.a", "next_cursor_expires_at": "2030-01-01T00:00:00Z"}
	end := map[string]any{"has_more": false, "next_cursor": nil, "next_cursor_expires_at": nil, "end_reason": "platform_limit"}
	page := func(p map[string]any) mockReply {
		return mockReply{body: map[string]any{"data": []int{1, 2}, "page": p, "meta": meta}, header: map[string]string{headerCreditsCharged: "5"}}
	}
	collect := func(p *Pager[int]) []int {
		var out []int
		for v, err := range p.All() {
			if err != nil {
				t.Fatal(err)
			}
			out = append(out, v)
		}
		return out
	}
	ctx := context.Background()
	h.mock.reply(page(more), page(end))
	p := iterate[int](ctx, h.t, "/v1/test/list", url.Values{"handle": {"h"}}, 5, IterateOptions{}, nil)
	// The API's end reason and the SDK's guards are separate: StopReason StopEnd, EndReason the API's page.end_reason.
	if got := collect(p); !reflect.DeepEqual(got, []int{1, 2, 1, 2}) || p.PagesFetched() != 2 || p.CreditsCharged() != 10 ||
		p.StopReason() != StopEnd || p.EndReason() != "platform_limit" {
		t.Errorf("all: %v %d %d %q %q", got, p.PagesFetched(), p.CreditsCharged(), p.StopReason(), p.EndReason())
	}
	if r := h.mock.reqs()[1]; r.Query.Get("cursor") != "c1.a" || r.Query.Get("handle") != "h" {
		t.Errorf("second page query: %v", r.Query)
	}
	h.mock.reply(page(more), page(more), page(more))
	p = iterate[int](ctx, h.t, "/v1/test/list", url.Values{"cursor": {"c1.start"}}, 5, IterateOptions{MaxPages: Int(2)}, nil)
	if got := collect(p); len(got) != 4 || p.StopReason() != StopMaxPages || p.EndReason() != "" || h.mock.reqs()[2].Query.Get("cursor") != "c1.start" {
		t.Errorf("max pages: %v %q", got, p.StopReason())
	}
	p = iterate[int](ctx, h.t, "/v1/test/list", nil, 5, IterateOptions{MaxCredits: Int(9)}, nil)
	if got := collect(p); len(got) != 2 || p.PagesFetched() != 1 || p.CreditsCharged() != 5 || p.StopReason() != StopMaxCredits {
		t.Errorf("max credits: %v %q", got, p.StopReason())
	}
	p = iterate[int](ctx, h.t, "/v1/test/list", nil, 5, IterateOptions{MaxCredits: Int(4)}, nil)
	if got := collect(p); len(got) != 0 || p.StopReason() != StopMaxCredits {
		t.Errorf("no budget: %v %q", got, p.StopReason())
	}
	// A zero limit stops at once (as in the other SDKs); nil is no limit.
	requests := len(h.mock.reqs())
	for _, g := range []IterateOptions{{MaxCredits: Int(0)}, {MaxPages: Int(0)}} {
		p = iterate[int](ctx, h.t, "/v1/test/list", nil, 5, g, nil)
		if got := collect(p); len(got) != 0 || p.PagesFetched() != 0 || len(h.mock.reqs()) != requests {
			t.Errorf("zero guard %+v: %v, %d pages", g, got, p.PagesFetched())
		}
	}
}

