func TestRawAndPartial(t *testing.T) {
	h := setup(t)
	body := map[string]any{"data": map[string]any{"a": 1, "brand_new": true}, "meta": meta, "brand_new_member": 1}
	h.mock.reply(mockReply{body: body}, mockReply{body: body})
	res, err := get[struct{ A int }](context.Background(), h.t, "/v1/test/item", nil, nil)
	if err != nil || res.Data.A != 1 || res.Partial || !strings.Contains(string(res.Raw), "brand_new") || !strings.Contains(string(res.Body), "brand_new_member") {
		t.Fatalf("raw: %+v %v", res, err)
	}
	// With fields= the data carries only the selected members: Data is left zero (nothing invented), Raw holds them.
	res, err = get[struct{ A int }](context.Background(), h.t, "/v1/test/item", url.Values{"fields": {"a"}}, nil)
	if err != nil || res.Data.A != 0 || !res.Partial || !strings.Contains(string(res.Raw), `"a":1`) {
		t.Fatalf("partial: %+v %v", res, err)
	}
	end := map[string]any{"has_more": false, "next_cursor": nil, "next_cursor_expires_at": nil}
	h.mock.reply(mockReply{body: map[string]any{"data": []any{map[string]any{"a": 1}}, "page": end, "meta": meta}})
	p := iterate[struct{ A int }](context.Background(), h.t, "/v1/test/list", url.Values{"fields": {"a"}}, 5, IterateOptions{}, nil)
	for _, err := range p.All() {
		if !errors.Is(err, ErrPartialItems) {
			t.Errorf("All with fields: %v", err)
		}
	}
	var raws []string
	for raw, err := range p.AllRaw() {
		if err != nil {
			t.Fatal(err)
		}
		raws = append(raws, string(raw))
	}
	if !reflect.DeepEqual(raws, []string{`{"a":1}`}) {
		t.Errorf("AllRaw: %v", raws)
	}
}
